// Registers the external-automation webhook on the six projects that have no native automation.
const URL = 'https://efuturemedia.app.n8n.cloud/webhook/lokalise-external-fill';
// Same events the native automations fire on: a new key, or an EN source edit.
const EVENTS = ['project.key.added', 'project.keys.added', 'project.translation.updated', 'project.translations.updated'];
const P = [
  ['Mobitrace','14240418673f52ae29a007.74392007'],
  ['Mobitrace - backend/emails','9274956467e3e224807498.79791832'],
  ['My Image - Backend','50011170688b3050b0a7f8.40995136'],
  ['Unicopy','35679002689c4f3ba6dd50.31739712'],
  ['Unicopy (backend)','1600517668d38be7f36ba4.51132642'],
  ['WAPP','4780438967fe077b4e6484.83742970']
];
const out = [];
for (const p of P) {
  out.push({ json: { name: p[0], pid: p[1], url: 'https://api.lokalise.com/api2/projects/' + p[1] + '/webhooks', body: { url: URL, events: EVENTS } } });
}
return out;

const reqs = $('Config').all();
const res = $input.all();
const rows = [];
for (let i = 0; i < res.length; i++) {
  const meta = (reqs[i] || { json: {} }).json;
  const r = res[i].json || {};
  const b = r.body || {};
  const w = b.webhook || null;
  rows.push({ project: meta.name, pid: meta.pid, status: r.statusCode,
    webhook_id: w ? w.webhook_id : null, secret: w ? 'set' : null,
    events: w ? (w.events || []).join(',') : null,
    error: w ? null : JSON.stringify(b).slice(0, 300) });
}
return [{ json: { results: rows } }];
